/// <summary>
/// PaffH 01.06.21
/// </summary>
/// <param name = "_productRecId">EcoResProductRecId</param>
/// <param name = "_languageId">LanguageId</param>
/// <returns>concatination Name, NDXProductName2</returns>
public static NDXEcoResProductNameConcat getNameOrDefaultNameConcat(
    EcoResProductRecId  _productRecId,
    LanguageId          _languageId =  CompanyInfo::languageId())
{
    EcoResProductTranslation ecoResProductTranslation;

    ecoResProductTranslation = EcoResProductTranslation::NDXfindByProductOrSystemLanguage(
        _productRecId, _languageId, fieldNum(EcoResProductTranslation, Name));

    return strFmt('%1 %2', ecoResProductTranslation.NDXProductName1, ecoResProductTranslation.NDXProductName2);
}

/// <summary>
/// PaffH 01.06.21
/// </summary>
/// <param name = "_productRecId">EcoResProductRecId</param>
/// <param name = "_languageId">LanguageId</param>
/// <param name = "_translationFieldId">FieldId</param>
/// <remarks>because findByProductOrSystemLanguage() is private, this method had to be copied</remarks>
/// <returns>EcoResProductTranslation</returns>
public static EcoResProductTranslation NDXfindByProductOrSystemLanguage(
    EcoResProductRecId  _productRecId,
    LanguageId          _languageId = currentUserLanguage(),
    FieldId             _translationFieldId = fieldNum(EcoResProductTranslation, Name),
    boolean _forUpdate = false)
{
    EcoResProductTranslation    ecoResProductTranslation;
    LanguageId                  systemLanguageId;

    ecoResProductTranslation = EcoResProductTranslation::findByProductLanguage(
        _productRecId, _languageId, _forUpdate);

    //no translation record or no value provided - fallback to system language
    if (!ecoResProductTranslation.RecId || !ecoResProductTranslation.(_translationFieldId))
    {
        systemLanguageId = SystemParameters::getSystemLanguageId();
        if (systemLanguageId != _languageId)
        {
            ecoResProductTranslation = EcoResProductTranslation::findByProductLanguage(
                _productRecId, systemLanguageId, _forUpdate);
        }
    }

    return ecoResProductTranslation;
}

/// <summary>
/// PaffH 01.06.21
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(EcoResProductTranslation,NDXProductName1 ) :
            SysDictField dictFieldName = new SysDictField(tableNum(EcoResProductTranslation), fieldNum(EcoResProductTranslation, Name));
            this.Name = subStr(this.NDXProductName1, 1, dictFieldName.fieldSize());
            break;
    }
}

/// <summary>
/// PaffH 09.06.21
/// initialize NDXProductName1 with Name (if empty)
/// </summary>
public static void NDXinitNDXProductName1()
{
    EcoResProductTranslation ecoResProductTranslation;
    if (Box::okCancel("@NDX:NDXInitEcoResProductTranslation_NDXProductName1YesNo", DialogButton::Cancel) == DialogButton::Cancel)
    {
        return;
    }
    update_recordset ecoResProductTranslation
        setting NDXProductName1 = ecoResProductTranslation.Name
        where ecoResProductTranslation.NDXProductName1 == '';
    Info(strFmt("@NDX:NDXInitEcoResProductTranslation_NDXProductName1",ecoResProductTranslation.RowCount()));
}

/// <summary>
/// PaffH 26.08.21
/// fill NDXProductName1 / Name
/// </summary>
/// <param name = "common">EcoResProductTranslation</param>
public static void fillProductName1(Common common)
{
    EcoResProductTranslation ecoResProductTranslation = common as EcoResProductTranslation;
    if (!ecoResProductTranslation.NDXProductName1 && ecoResProductTranslation.Name)
    {
        ecoResProductTranslation.NDXProductName1 = ecoResProductTranslation.Name;
    }
    else if (ecoResProductTranslation.NDXProductName1 && !ecoResProductTranslation.Name)
    {
        ecoResProductTranslation.Name = subStr(ecoResProductTranslation.NDXProductName1, 1, strLen(ecoResProductTranslation.Name));
    }
}
